// SPDX-License-Identifier: MIT
// Dyevat (G601, art-master-flex), plain C++17 for the Unreal binding. A port of tools/minigames/dyevat.py, which
// stays the rules authority. Seeding is CPython-compatible (DaedalusPyRandomCore.h, "dyevat:<seed>:<difficulty>") and
// the only draws are randrange at setup (a Fisher-Yates shuffle from the back); nothing is random after. Byte parity
// goes through engines/unreal/core-test/dyevat_parity.txt (dyevat_core_test.cpp), generated by
// tools/minigames/dyevat_parity.py.
//
// Rules: Hues x Capacity pigment layers shuffled into the first Hues vats, Empty more vats start empty. A pour moves
// the top run of one vat (every touching layer of its top hue) onto an empty vat or a vat whose top is the same hue,
// as many layers as fit. A vat full of one hue seals (+SealScore) and is locked. Every hue sealed wins (+PourBonus per
// pour left); spent pours or no legal pour left lose. No heap in the game state, no exceptions.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <array>
#include <cstdint>
#include <string>

namespace daedalus { namespace dyevat {

inline const char* GameId() { return "dyevat"; }
inline const char* Title() { return "Dyevat"; }

constexpr int Capacity = 4;
constexpr int MaxVats = 8;
constexpr int SealScore = 5, PourBonus = 3;

struct Difficulty { const char* Name; int Hues; int Empty; int Pours; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 3, 2, 30 }, { "normal", 4, 2, 40 }, { "hard", 5, 2, 50 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

struct Vat
{
	std::array<int, Capacity> Layers{};   // bottom to top, hues 1..Hues
	int Count = 0;
	int Top() const noexcept { return Count > 0 ? Layers[static_cast<size_t>(Count - 1)] : 0; }
	bool FullOneHue() const noexcept
	{
		if (Count != Capacity) return false;
		for (int I = 1; I < Count; ++I) if (Layers[static_cast<size_t>(I)] != Layers[0]) return false;
		return true;
	}
	/** Length of the top run (0 when empty). */
	int Run() const noexcept
	{
		int N = 0;
		while (N < Count && Layers[static_cast<size_t>(Count - 1 - N)] == Top()) ++N;
		return N;
	}
};

struct Pour { int From = 0, To = 0; };
/** What one pour would do (Game.preview). */
struct Outcome { int Moved = 0, Seals = 0, OntoEmpty = 0; };

struct Game
{
	int Hues = 0, VatCount = 0, PourLimit = 0;
	std::array<Vat, MaxVats> Vats{};
	std::array<bool, MaxVats> Sealed{};
	int Pours = 0, Score = 0;
	Pour Last{ -1, -1 };
	bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, Illegal, GameOver };

	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		const Difficulty* D = FindDifficulty(DifficultyName);
		if (!D) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Hues = D->Hues; VatCount = D->Hues + D->Empty; PourLimit = D->Pours;
		std::array<int, MaxVats * Capacity> Pool{};
		const int N = Hues * Capacity;
		for (int I = 0; I < N; ++I) Pool[static_cast<size_t>(I)] = I / Capacity + 1;
		for (int I = N - 1; I > 0; --I)
		{
			const int J = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(I + 1)));
			const int T = Pool[static_cast<size_t>(I)]; Pool[static_cast<size_t>(I)] = Pool[static_cast<size_t>(J)]; Pool[static_cast<size_t>(J)] = T;
		}
		Vats = {}; Sealed = {};
		for (int V = 0; V < Hues; ++V)
		{
			for (int L = 0; L < Capacity; ++L) Vats[static_cast<size_t>(V)].Layers[static_cast<size_t>(L)] = Pool[static_cast<size_t>(V * Capacity + L)];
			Vats[static_cast<size_t>(V)].Count = Capacity;
		}
		for (int V = 0; V < VatCount; ++V) Sealed[static_cast<size_t>(V)] = Vats[static_cast<size_t>(V)].FullOneHue();
		Pours = PourLimit; Score = 0; Last = { -1, -1 }; Over = Won = false;
		return true;
	}

	const Vat& At(int V) const noexcept { return Vats[static_cast<size_t>(V)]; }
	bool IsSealed(int V) const noexcept { return Sealed[static_cast<size_t>(V)]; }
	int SealedCount() const noexcept { int N = 0; for (int V = 0; V < VatCount; ++V) N += IsSealed(V) ? 1 : 0; return N; }

	bool Legal(int A, int B) const noexcept
	{
		if (A == B || A < 0 || B < 0 || A >= VatCount || B >= VatCount) return false;
		if (IsSealed(A) || IsSealed(B) || At(A).Count == 0 || At(B).Count >= Capacity) return false;
		return At(B).Count == 0 || At(B).Top() == At(A).Top();
	}
	bool AnyLegal() const noexcept
	{
		for (int A = 0; A < VatCount; ++A) for (int B = 0; B < VatCount; ++B) if (Legal(A, B)) return true;
		return false;
	}

	bool Preview(int A, int B, Outcome& Out) const noexcept
	{
		if (!Legal(A, B)) return false;
		const Vat& From = At(A); const Vat& To = At(B);
		Out.Moved = From.Run() < Capacity - To.Count ? From.Run() : Capacity - To.Count;
		Out.OntoEmpty = To.Count == 0 ? 1 : 0;
		bool Same = true;
		for (int I = 0; I < To.Count; ++I) if (To.Layers[static_cast<size_t>(I)] != From.Top()) Same = false;
		Out.Seals = (To.Count + Out.Moved == Capacity && Same) ? 1 : 0;
		return true;
	}

	/** Game.act. `Result` mirrors the Python result text. */
	Act Step(Pour P, std::string& Result)
	{
		if (Over) return Act::GameOver;
		if (!Legal(P.From, P.To)) { Result = "illegal: that pour is not allowed"; return Act::Illegal; }
		Vat& From = Vats[static_cast<size_t>(P.From)]; Vat& To = Vats[static_cast<size_t>(P.To)];
		const int Moved = From.Run() < Capacity - To.Count ? From.Run() : Capacity - To.Count;
		for (int I = 0; I < Moved; ++I)
		{
			To.Layers[static_cast<size_t>(To.Count++)] = From.Layers[static_cast<size_t>(From.Count - 1)];
			From.Layers[static_cast<size_t>(--From.Count)] = 0;
		}
		--Pours; Last = P;
		int Seals = 0;
		if (To.FullOneHue()) { Sealed[static_cast<size_t>(P.To)] = true; Seals = 1; Score += SealScore; }
		const std::string Head = std::to_string(P.From) + "," + std::to_string(P.To) + ": " + std::to_string(Moved) + " poured";
		if (SealedCount() == Hues) { Score += PourBonus * Pours; Over = Won = true; Result = Head + ", every hue sealed"; return Act::Ok; }
		if (Pours <= 0) { Over = true; Result = Head + "; the pours are spent"; return Act::Ok; }
		if (!AnyLegal()) { Over = true; Result = Head + "; no pour is left"; return Act::Ok; }
		Result = Head + ", " + std::to_string(Seals) + " sealed, " + std::to_string(SealedCount()) + "/" + std::to_string(Hues) + " hues";
		return Act::Ok;
	}

	/** Game.demo_action (the Dyer): skip undoing the last pour and whole one-hue moves into an empty vat; prefer a seal,
	 *  then a matching top over an empty vat, then most layers, then emptying the source; ties by from, to. */
	Pour DemoAction() const noexcept
	{
		bool HaveBest = false, HaveFallback = false;
		Pour Best{}, Fallback{};
		int BestKey[4] = { 0, 0, 0, 0 };
		for (int A = 0; A < VatCount; ++A)
			for (int B = 0; B < VatCount; ++B)
			{
				Outcome O;
				if (!Preview(A, B, O)) continue;
				if (!HaveFallback) { Fallback = { A, B }; HaveFallback = true; }
				if (B == Last.From && A == Last.To) continue;
				if (O.OntoEmpty && O.Moved == At(A).Count) continue;
				const int Key[4] = { -O.Seals, O.OntoEmpty, -O.Moved, -(O.Moved == At(A).Count ? 1 : 0) };
				bool Better = !HaveBest;
				for (int K = 0; !Better && K < 4; ++K)
				{
					if (Key[K] < BestKey[K]) { Better = true; break; }
					if (Key[K] > BestKey[K]) break;
				}
				if (Better) { HaveBest = true; Best = { A, B }; for (int K = 0; K < 4; ++K) BestKey[K] = Key[K]; }
			}
		if (HaveBest) return Best;
		if (HaveFallback) return Fallback;
		return { 0, 1 };
	}

	/** Each vat bottom to top, '-' when empty, joined by ';' (parity text). */
	std::string VatsString() const
	{
		std::string S;
		for (int V = 0; V < VatCount; ++V)
		{
			if (V) S += ';';
			if (At(V).Count == 0) S += '-';
			for (int I = 0; I < At(V).Count; ++I) S += static_cast<char>('0' + At(V).Layers[static_cast<size_t>(I)]);
		}
		return S;
	}
	std::string SealedString() const
	{
		std::string S;
		for (int V = 0; V < VatCount; ++V) S += IsSealed(V) ? '1' : '0';
		return S;
	}
};

} }
